widget.solution:
def inverse_mod(a, n):
    r0, r1 = n, a % n
    t0, t1 = 0, 1
    while r1:
        q = r0 // r1
        r0, r1 = r1, r0 - q * r1
        t0, t1 = t1, t0 - q * t1
    if r0 != 1:
        return None
    return t0 % n
